function record(id, q, correctText, why, difficulty, topicId, subtopic, chapterId, answerFamily, distractors, source, claim) {
  return {
    id, q, correctText, why, difficulty, topicId, subtopic, chapterId, answerFamily,
    distractors: distractors.map(([text, rationale]) => ({ text, rationale })),
    source: { ...SOURCES[source], claim: `${claim} This supports the answer: ${correctText}.`, status: 'verified', lastVerified: CHECKED },
    verifiedAt: CHECKED,
  };
}

